const Utils = require('../utils');

const RadioAssets = require('../radio/assets');
const CheckboxAssets = require('../checkbox/assets');
let ButtonAssets, SwitchAssets, ToastAssets, KeyboardAssets;
try { ButtonAssets = require('../button/assets'); } catch (e) { ButtonAssets = []; }
try { SwitchAssets = require('../switch/assets'); } catch (e) { SwitchAssets = []; }
try { ToastAssets = require('../toast/assets'); } catch (e) { ToastAssets = []; }
try { KeyboardAssets = require('../keyboard/assets'); } catch (e) { KeyboardAssets = {}; }

function normalizeKeyboardAssets(obj) {
  const arr = [];
  if (!obj || typeof obj !== 'object') return arr;
  Object.keys(obj).forEach((id) => {
    const src = obj[id];
    if (typeof src !== 'string') return;
    const lower = src.toLowerCase();
    let type = 'img';
    if (lower.endsWith('.mp3') || lower.endsWith('.wav') || lower.endsWith('.ogg')) type = 'audio';
    arr.push({ type, id, src });
  });
  return arr;
}

function normalizeArray(assets) {
  if (!assets) return [];
  if (Array.isArray(assets)) return assets;
  if (typeof assets === 'object') return normalizeKeyboardAssets(assets);
  return [];
}

const FEATURE_ASSETS = {
  core: [],
  radio: normalizeArray(RadioAssets),
  checkbox: normalizeArray(CheckboxAssets),
  button: normalizeArray(ButtonAssets),
  switch: normalizeArray(SwitchAssets),
  toast: normalizeArray(ToastAssets),
  keyboard: normalizeArray(KeyboardAssets)
};

const AssetsRegistry = {
  ensured: false,
  ensuredFeatures: new Set(),

  ensure(features) {
    if (!features || !features.length) return;
    // Default assets path if not set
    if (typeof AFRAME !== 'undefined' && !AFRAME.ASSETS_PATH) {
      AFRAME.ASSETS_PATH = './assets';
    }

    // Build a deduped list by id
    const all = [];
    const ids = new Set();
    features.forEach((f) => {
      const list = FEATURE_ASSETS[f] || [];
      list.forEach((item) => {
        if (!item || !item.id || ids.has(item.id)) return;
        ids.add(item.id);
        all.push(item);
      });
      this.ensuredFeatures.add(f);
    });

    if (all.length) {
      Utils.preloadAssets(all);
    }
  },

  ensureAll() {
    this.ensure(Object.keys(FEATURE_ASSETS));
    this.ensured = true;
  }
};

module.exports = AssetsRegistry;
